1	/**
2	 * @file scene_design_e.c
3	 * @brief WP-DESIGN3/R1 方案 E「模式盘 Dial」完整设计：Helm 版。
4	 *
5	 * 视觉主线：一枚 160px 的舵轮。外圈 24 格细刻度 + 4 根主刻度，选中扇区用
6	 * 浅色填充 + 深色边（不发光），盘心是一块纸色轮毂，轮毂里放模式名/描述/关键
7	 * 数字；指针是一根从轮毂边缘伸向扇区的舵柄，末端一短横。
8	 *
9	 * 十屏由 SIM_DESIGN_SCREEN 选：
10	 *   main | rotate | longpress | ride | nav | record | settings | display |
11	 *   sensor | about（也接受 0..9；窗口模式按 1..9 / 0 直接切屏）。
12	 *
13	 * 导航页接**真 vmap 组件**（SIM_WITH_UI=ON 时，和 `--scene vmap` 同一份
14	 * vmap_view + 设备瓦片）；未编 UI 时退回一张同色板的示意地图（会打印提示）。
15	 *
16	 * 仅模拟器出图，不链接进板端。
17	 */
18	
19	#include <math.h>
20	#include <stdio.h>
21	#include <stdlib.h>
22	#include <string.h>
23	
24	#include "design2_common.h"
25	
26	#ifdef SIM_WITH_UI
27	#include "sim_config.h"
28	#include "NaviArrow.h"
29	#include "vmap_config.h"
30	#include "vmap_view.h"
31	#endif
