33	/* ── 色板（宣纸白 / 单一墨绿 / 更硬的灰阶）───────────────────────
34	 *
35	 * 对比上一轮：
36	 *   - 次要文字 #8B8781 → #6E6A63（约 58% 黑），最短 11px；
37	 *   - 发丝线 8~10% 黑 → #C9C5BD（约 22% 黑）；
38	 *   - 表盘轨道 12% 黑 → #C4BEB2（约 23% 黑），刻度 #8F8A7F（约 44% 黑）。
39	 * 这三处正是上一轮阳光档最先消失的元素。 */
40	#define E_BG      0xF7F5F0u   /**< 纸底 */
41	#define E_INK     0x141518u   /**< 主文字 */
42	#define E_MUTE    0x6E6A63u   /**< 次要文字（≈58% 黑） */
43	#define E_ACC     0x0B6E4Fu   /**< 唯一强调色（墨绿） */
44	#define E_TRACK   0xBDB7AAu   /**< 表盘整圈轨道（≈26% 黑） */
45	#define E_TICK    0x8F8A7Fu   /**< 刻度（≈44% 黑） */
46	#define E_HAIR    0xB9B4AAu   /**< 1px 分隔线（≈28% 黑，阳光档仍可见） */
47	#define E_SECTOR  0xDCE9E2u   /**< 选中扇区浅填充 */
48	#define E_MAP     0xE9E6DFu   /**< 示意图纸（无 vmap 时） */
49	#define E_ROAD    0xFBF9F4u   /**< 示意道路 */
50	#define E_WHITE   0xFFFFFFu   /**< 地图上的提示条 */
51	
52	#define E_INK_S   "141518"
53	
54	/* ── 字号阶梯：全设计只有这 6 档（见 FONT_PLAN.md）──────────────── */
55	enum {
56	    E_PX_HERO  = 64,   /**< 骑行时速 */
57	    E_PX_TITLE = 30,   /**< 页标题 / 盘心模式名 / 转向距离 */
58	    E_PX_VALUE = 22,   /**< 关键数字 / 指标值 / 记录里程 */
59	    E_PX_BODY  = 15,   /**< 行名 / 日期 / 关于页值 */
60	    E_PX_SMALL = 12,   /**< 顶栏 / 描述 / 状态 / 单位说明 */
61	    E_PX_MICRO = 11,   /**< 图例 / 指标标签 / 单位（下限） */
62	};
63	
64	/* ── 屏幕 ──────────────────────────────────────────────────────── */
65	
66	enum {
67	    E_SCR_MAIN = 0,
68	    E_SCR_ROTATE,
69	    E_SCR_LONGPRESS,
70	    E_SCR_RIDE,
71	    E_SCR_NAV,
72	    E_SCR_RECORD,
73	    E_SCR_SETTINGS,
74	    E_SCR_DISPLAY,
75	    E_SCR_SENSOR,
76	    E_SCR_ABOUT,
77	    E_SCR_COUNT,
78	};
79	
80	static const char *const e_screen_names[E_SCR_COUNT] = {
81	    "main", "rotate", "longpress", "ride", "nav",
82	    "record", "settings", "display", "sensor", "about",
83	};
