87	static lv_obj_t *s_scr;
88	
89	/** 每屏各字号的 label 数（FONT_PLAN.md 的"出现次数"就是从这里抄的）。 */
90	static int s_font_use[128];
91	
92	static lv_font_t *e_font(int px)
93	{
94	    if (px >= 0 && px < 128) {
95	        s_font_use[px]++;
96	    }
97	    return sim_font_cjk(px);
98	}
