100	/** 图例走 design2_common 的 d2_legend，字号固定 E_PX_MICRO，单独记一次。 */
101	static void e_legend(lv_obj_t *p, int y, const char *markup)
102	{
103	    s_font_use[E_PX_MICRO]++;
104	    d2_legend(p, y, E_PX_MICRO, E_MUTE, markup);
105	}
