107	/**
108	 * @brief lv_line 的点数组池。
109	 *
110	 * LVGL 的 lv_line_set_points() 只存指针不拷贝；动态算出来的刻度/舵柄如果放
111	 * 栈上会立刻失效。这里给整屏一个固定池，重建时归零，避免每根线 malloc。
112	 */
113	#define E_PTS_MAX 192
114	static lv_point_precise_t s_pts[E_PTS_MAX][2];
115	static int s_pts_n;
116	
117	static void e_pts_reset(void)
118	{
119	    s_pts_n = 0;
120	}
121	
122	static const lv_point_precise_t *e_seg(int x1, int y1, int x2, int y2)
123	{
124	    if (s_pts_n >= E_PTS_MAX) {
125	        s_pts_n = 0;
126	    }
127	    lv_point_precise_t *p = s_pts[s_pts_n++];
128	
129	    p[0].x = x1;
130	    p[0].y = y1;
131	    p[1].x = x2;
132	    p[1].y = y2;
133	    return p;
134	}
135	
136	static lv_obj_t *e_lab(lv_obj_t *p, const char *txt, int px, uint32_t hex,
137	                       int x, int y)
138	{
139	    if (px >= 0 && px < 128) {
140	        s_font_use[px]++;
141	    }
142	    return d_label(p, txt, px, hex, x, y);
143	}
144	
145	static lv_obj_t *e_lab_w(lv_obj_t *p, const char *txt, int px, uint32_t hex,
146	                         int x, int y, int w, lv_text_align_t align)
147	{
148	    if (px >= 0 && px < 128) {
149	        s_font_use[px]++;
150	    }
151	    return d_label_w(p, txt, px, hex, x, y, w, align);
152	}
153	
154	/** 1px 分隔线：用已经压到 22% 黑的颜色，不再叠加透明度。 */
155	static void e_hair(lv_obj_t *p, int x, int y, int w)
156	{
157	    (void)d_hline(p, x, y, w, E_HAIR, LV_OPA_COVER);
158	}
159	
160	static void e_top(lv_obj_t *p, const char *left, const char *right)
161	{
162	    e_lab(p, left, E_PX_SMALL, E_MUTE, 24, 13);
163	    e_lab_w(p, right, E_PX_SMALL, E_MUTE, 140, 13, 76, LV_TEXT_ALIGN_RIGHT);
164	}
165	
166	/** 单位：贴着数值基线放，11px。 */
167	static void e_unit(lv_obj_t *row, const char *unit, int pad_bottom)
168	{
169	    lv_obj_t *u = lv_label_create(row);
170	
171	    lv_label_set_text(u, unit);
172	    lv_obj_set_style_text_font(u, e_font(E_PX_MICRO), 0);
173	    lv_obj_set_style_text_color(u, lv_color_hex(E_MUTE), 0);
174	    lv_obj_set_style_pad_bottom(u, pad_bottom, 0);
175	}
176	
177	/** 数值 + 单位的一行（22px 值 + 11px 单位）。 */
178	static void e_value_row(lv_obj_t *p, int x, int y, int w, const char *value,
179	                        const char *unit, int px)
180	{
181	    lv_obj_t *row = d_stack(p, x, y, w, px + 6, LV_FLEX_ALIGN_CENTER, 3);
182	    lv_obj_t *v = lv_label_create(row);
183	
184	    lv_label_set_text(v, value);
185	    lv_obj_set_style_text_font(v, e_font(px), 0);
186	    lv_obj_set_style_text_color(v, lv_color_hex(E_INK), 0);
187	    if (unit && unit[0]) {
188	        e_unit(row, unit, px >= 22 ? 4 : 2);
189	    }
190	}
191	
192	/** 圆弧（可关闭圆角端帽 = 扇区/仪表用；开 = 进度用）。 */
193	static lv_obj_t *e_arc(lv_obj_t *p, int cx, int cy, int d, int thickness,
194	                       int start, int span, uint32_t hex, bool rounded)
195	{
196	    lv_obj_t *arc = lv_arc_create(p);
197	
198	    lv_obj_set_size(arc, d, d);
199	    lv_obj_set_pos(arc, cx - d / 2, cy - d / 2);
200	    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
201	    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
202	    lv_obj_set_style_pad_all(arc, 0, 0);
203	    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
204	    lv_obj_set_style_border_width(arc, 0, 0);
205	    lv_obj_set_style_outline_width(arc, 0, 0);
206	    lv_obj_set_style_shadow_width(arc, 0, 0);
207	
208	    lv_obj_set_style_arc_opa(arc, LV_OPA_TRANSP, LV_PART_MAIN);
209	    lv_obj_set_style_arc_width(arc, 0, LV_PART_MAIN);
210	    lv_obj_set_style_arc_rounded(arc, false, LV_PART_MAIN);
211	
212	    lv_obj_set_style_arc_opa(arc, LV_OPA_COVER, LV_PART_INDICATOR);
213	    lv_obj_set_style_arc_width(arc, thickness, LV_PART_INDICATOR);
214	    lv_obj_set_style_arc_color(arc, lv_color_hex(hex), LV_PART_INDICATOR);
215	    lv_obj_set_style_arc_rounded(arc, rounded, LV_PART_INDICATOR);
216	
217	    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_KNOB);
218	    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
219	    lv_obj_set_style_pad_all(arc, 0, LV_PART_KNOB);
220	
221	    /* 归一到 0..359：LVGL 接受 start > end（跨 0 点）。 */
222	    lv_arc_set_bg_angles(arc, ((start % 360) + 360) % 360,
223	                         (((start + span) % 360) + 360) % 360);
224	    lv_arc_set_rotation(arc, 0);
225	    lv_arc_set_range(arc, 0, 100);
226	    lv_arc_set_value(arc, 100);
227	    return arc;
228	}
229	
230	/**
231	 * @brief 真径向刻度。
232	 *
233	 * design2_common 的 d2_tick() 用横/竖色块近似，斜刻度会变成水平短杠；
234	 * 舵轮要的是从圆心放射的线，所以这里直接 lv_line。
235	 */
236	static void e_tick(lv_obj_t *p, int cx, int cy, int deg, int r1, int r2,
237	                   int thickness, uint32_t hex)
238	{
239	    const double a = (double)deg * 3.14159265358979 / 180.0;
240	    const int x1 = cx + (int)lround(sin(a) * r1);
241	    const int y1 = cy - (int)lround(cos(a) * r1);
242	    const int x2 = cx + (int)lround(sin(a) * r2);
243	    const int y2 = cy - (int)lround(cos(a) * r2);
244	
245	    (void)d2_poly(p, e_seg(x1, y1, x2, y2), 2, thickness, hex, true);
246	}
247	
248	/** 舵柄：从轮毂边缘 r0 指向 r1，末端一根垂直于半径的短横。 */
249	static void e_tiller(lv_obj_t *p, int cx, int cy, int deg, int r0, int r1)
250	{
251	    const double a = (double)deg * 3.14159265358979 / 180.0;
252	    const double sx = sin(a);
253	    const double sy = -cos(a);
254	    const double px = cos(a);
255	    const double py = sin(a);
256	    const int x0 = cx + (int)lround(sx * r0);
257	    const int y0 = cy + (int)lround(sy * r0);
258	    const int x1 = cx + (int)lround(sx * r1);
259	    const int y1 = cy + (int)lround(sy * r1);
260	
261	    (void)d2_poly(p, e_seg(x0, y0, x1, y1), 2, 3, E_INK, true);
262	    (void)d2_poly(p, e_seg(x1 - (int)lround(px * 8),
263	                           y1 - (int)lround(py * 8),
264	                           x1 + (int)lround(px * 8),
265	                           y1 + (int)lround(py * 8)),
266	                  2, 3, E_INK, true);
267	}
268	
269	/**
270	 * @brief 舵轮盘面。
271	 *
272	 * @param sel_deg 选中扇区中心（从 12 点顺时针；-1 = 不画扇区）
273	 * @param ptr_deg 舵柄角度（从 12 点顺时针）
274	 */
275	static void e_dial(lv_obj_t *p, int cx, int cy, int sel_deg, int ptr_deg,
276	                   bool progress)
277	{
278	    /* 整圈轨道：2px，23% 黑。 */
279	    (void)d2_ring(p, cx, cy, 160, 2, E_TRACK);
280	
281	    /* 选中扇区：24px 浅绿带 + 内外两条深绿边。 */
282	    if (sel_deg >= 0) {
283	        const int a = sel_deg - 90;   /* 转成 LVGL：0°=3 点 */
284	
285	        (void)e_arc(p, cx, cy, 144, 24, a - 26, 52, E_SECTOR, false);
286	        /* 只画外沿：内沿由轮毂的 1px 边充当，避免两条线挤在一起。 */
287	        (void)e_arc(p, cx, cy, 170, 2, a - 26, 52, E_ACC, false);
288	    }
289	
290	    /* 24 格细刻度 + 4 根主刻度（0/90/180/270）。
291	     * 放在轨道**内侧**（r=66..74）：刻度不会扎进 3/9 点的模式名；
292	     * 选中扇区盖住刻度环，刻度再画在扇区之上，像一圈章节环。 */
293	    for (int i = 0; i < 24; i++) {
294	        const int deg = i * 15;
295	        const bool major = (i % 6 == 0);
296	
297	        e_tick(p, cx, cy, deg, major ? 66 : 69, 74,
298	               major ? 3 : 1, major ? E_INK : E_TICK);
299	    }
300	
301	    /* 舵柄：从盘心文字区外沿伸到扇区外沿。 */
302	    e_tiller(p, cx, cy, ptr_deg, 56, 84);
303	
304	    /* 长按进度：轮毂外一圈 270° 弧，半满 50%。 */
305	    if (progress) {
306	        lv_obj_t *pr;
307	
308	        (void)e_arc(p, cx, cy, 128, 3, 135, 270, E_TRACK, true);
309	        pr = e_arc(p, cx, cy, 128, 4, 135, 270, E_ACC, true);
310	        lv_arc_set_value(pr, 50);
311	    }
312	}
313	
314	/** 四个模式名：12/3/6/9 点，选中 15px 黑、未选中 12px 灰。 */
315	static void e_mode_labels(lv_obj_t *p, int cx, int cy, int on)
316	{
317	    static const char *const names[4] = { "骑行", "导航", "记录", "设置" };
318	    static const int lx[4] = { 0, 1, 0, -1 };
319	    static const int ly[4] = { -1, 0, 1, 0 };
320	
321	    for (int i = 0; i < 4; i++) {
322	        const bool sel = (i == on);
323	        const int px = sel ? E_PX_BODY : E_PX_SMALL;
324	        const int x = cx + lx[i] * 96 - 20;
325	        const int y = cy + ly[i] * 104 - (sel ? 10 : 8);
326	
327	        e_lab_w(p, names[i], px, sel ? E_INK : E_MUTE, x, y, 40,
328	                LV_TEXT_ALIGN_CENTER);
329	    }
330	}
