342	static const e_mode_t e_modes[4] = {
343	    { "骑行", "实时数据 · 开始骑行", "42.6", "km", "上次骑行" },
344	    { "导航", "路线 · 转向提示", "8.4", "km", "剩余距离" },
345	    { "记录", "历史 · 数据回顾", "68", "km", "本周累计" },
346	    { "设置", "设备 · 显示 · 关于", "86", "%", "当前电量" },
347	};
