349	static void e_mode_center(lv_obj_t *p, int cx, int cy, const e_mode_t *m)
350	{
351	    lv_obj_t *name_stack = d_stack(p, cx - 80, cy - 56, 160, 40,
352	                                   LV_FLEX_ALIGN_CENTER, 0);
353	    lv_obj_t *name = lv_label_create(name_stack);
354	
355	    lv_label_set_text(name, m->name);
356	    lv_obj_set_style_text_font(name, e_font(E_PX_TITLE), 0);
357	    lv_obj_set_style_text_color(name, lv_color_hex(E_INK), 0);
358	
359	    e_lab_w(p, m->desc, E_PX_SMALL, E_MUTE, cx - 80, cy - 16, 160,
360	            LV_TEXT_ALIGN_CENTER);
361	    e_hair(p, cx - 16, cy + 4, 32);
362	    e_lab_w(p, m->caption, E_PX_MICRO, E_MUTE, cx - 80, cy + 9, 160,
363	            LV_TEXT_ALIGN_CENTER);
364	    e_value_row(p, cx - 60, cy + 24, 120, m->value, m->unit, E_PX_VALUE);
365	}
