367	static void e_main_common(int screen)
368	{
369	    const bool rotate = (screen == E_SCR_ROTATE);
370	    const bool press = (screen == E_SCR_LONGPRESS);
371	    const int on = rotate ? 1 : 0;
372	    const int ptr = rotate ? 45 : 0;
373	    const int sel = press ? -1 : (rotate ? 45 : 0);
374	    const e_mode_t *m = &e_modes[on];
375	
376	    d_bg(s_scr, E_BG);
377	
378	    if (rotate) {
379	        e_top(s_scr, "模式", "01 → 02");
380	    } else {
381	        e_top(s_scr, "模式", "01 / 04");
382	    }
383	
384	    e_dial(s_scr, 120, 146, sel, ptr, press);
385	    e_mode_labels(s_scr, 120, 146, on);
386	
387	    if (press) {
388	        /* 长按：模式名 / 描述 / 进度提示 / 50%，轮毂里不再放关键数字。 */
389	        lv_obj_t *name_stack = d_stack(s_scr, 40, 94, 160, 40,
390	                                       LV_FLEX_ALIGN_CENTER, 0);
391	        lv_obj_t *name = lv_label_create(name_stack);
392	
393	        lv_label_set_text(name, m->name);
394	        lv_obj_set_style_text_font(name, e_font(E_PX_TITLE), 0);
395	        lv_obj_set_style_text_color(name, lv_color_hex(E_INK), 0);
396	        e_lab_w(s_scr, m->desc, E_PX_SMALL, E_MUTE, 40, 134, 160,
397	                LV_TEXT_ALIGN_CENTER);
398	        e_lab_w(s_scr, "长按 1 进入", E_PX_SMALL, E_MUTE, 40, 154, 160,
399	                LV_TEXT_ALIGN_CENTER);
400	        /* 文字只用近黑；绿色只留给进度弧（形状）。 */
401	        e_lab_w(s_scr, "50%", E_PX_VALUE, E_INK, 40, 176, 160,
402	                LV_TEXT_ALIGN_CENTER);
403	    } else {
404	        e_mode_center(s_scr, 120, 146, m);
405	    }
406	
407	    e_legend(s_scr, 270,
408	              "短按 #" E_INK_S " 1# 旋转 · 长按 #" E_INK_S " 1# 进入");
409	    e_legend(s_scr, 286,
410	              "短按 #" E_INK_S " 2# 上一项 · 长按 #" E_INK_S " 2# 开始");
411	}
