950	        return E_SCR_MAIN;
951	    }
952	    for (int i = 0; i < E_SCR_COUNT; i++) {
953	        if (strcmp(s, e_screen_names[i]) == 0) {
954	            return i;
955	        }
956	    }
957	    /* 上一轮的四屏名保持可用。 */
958	    if (strcmp(s, "menu") == 0) {
959	        return E_SCR_SETTINGS;
960	    }
961	    if (s[0] >= '0' && s[0] <= '9' && s[1] == '\0') {
962	        return s[0] - '0';
963	    }
964	    fprintf(stderr,
965	            "sim: unknown SIM_DESIGN_SCREEN=%s "
966	            "(main|rotate|longpress|ride|nav|record|settings|display|sensor|about)\n",
967	            s);
968	    return E_SCR_MAIN;
969	}
