154	void d2_tick(lv_obj_t *p, int cx, int cy, int deg, int r1, int r2,
155	             int thickness, uint32_t hex)
156	{
157	    const double a = (double)deg * 3.14159265358979 / 180.0;
158	    const int x1 = cx + (int)lround(sin(a) * r1);
159	    const int y1 = cy - (int)lround(cos(a) * r1);
160	    const int x2 = cx + (int)lround(sin(a) * r2);
161	    const int y2 = cy - (int)lround(cos(a) * r2);
162	
163	    if (abs(x2 - x1) >= abs(y2 - y1)) {
164	        d_box(p, x1 < x2 ? x1 : x2, y1, abs(x2 - x1) + 1, thickness, hex,
165	              LV_OPA_COVER, thickness / 2);
166	    } else {
167	        d_box(p, x1, y1 < y2 ? y1 : y2, thickness, abs(y2 - y1) + 1, hex,
168	              LV_OPA_COVER, thickness / 2);
169	    }
170	}
