 * @file scene_design_g.c
 * @brief WP-DESIGN4/R1 「Helm 模式盘」第二版：模式色 + 信息密度 + 转场中间帧。
 *
 * 在 WP-DESIGN3/R1（scene_design_e.c）的舵轮语言上做两件事：
 *   1. 四个模式各有一组颜色（绿/蓝/橙/中性灰），色只画形状和面积，文字仍近黑；
 *   2. 每屏加一层信息：盘心副行 + 底部状态带、速度/心率双色带、路线进度条、
 *      记录行迷你柱、设置行图标底、关于页四色识别带。
 *
 * 十三屏由 SIM_DESIGN_SCREEN 选（前 10 屏与上一轮同名）：
 *   main | rotate | longpress | ride | nav | record | settings | display |
 *   sensor | about | anim_dial_rotate | anim_enter_ride | anim_back
 *
 * 只用于模拟器出图，不链接进板端。
 */

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "design2_common.h"

#ifdef SIM_WITH_UI
#include "sim_config.h"
#include "NaviArrow.h"
#include "vmap_config.h"
#include "vmap_view.h"
#endif

/* ── 色板 ────────────────────────────────────────────────────────
 *
 * 纸底/墨色/灰阶沿用 WP-DESIGN3（阳光档的地板不动）：
 *   名称       hex        角色
 *   G_BG        F7F5F0     纸底
 *   G_INK       141518     正文（近黑）
 *   G_MUTE      6E6A63     次要文字（58% 黑，≥40% 地板）
 *   G_HAIR      B9B4AA     1px 分隔线（28% 黑）
 *   G_TRACK     BDB7AA     盘面/滑杆未选轨道（26% 黑）
 *   G_TICK      8F8A7F     刻度（44% 黑）
 *   G_CARD      EFECE5     卡片底（比纸底深约 4%，RGB565 后 EFEBE6）
 *
 * 模式色（深色 = 形状/边/符号，浅色 = 填充；详见 evidence/COLOR.md）：
 *   模式    深色      浅色 20%   卡片 6%
 *   骑行    0B6E4F    C5DBCE     E6EFE6
 *   导航    1C63B0    CED7E6     E6EBEF
 *   记录    BD5908    EFD7C5     F7EBDE
 *   设置    505050    D6D2CE     EFEBE6
 */
#define G_BG      0xF7F5F0u
#define G_INK     0x141518u
#define G_MUTE    0x6E6A63u
#define G_HAIR    0xB9B4AAu
#define G_TRACK   0xBDB7AAu
#define G_TICK    0x8F8A7Fu
#define G_CARD    0xEFECE5u
#define G_RED     0xA62B1Fu   /**< 心率 Z5 / 识别带第四色以外不使用 */

#define G_INK_S   "141518"

enum { G_RIDE = 0, G_NAV = 1, G_RECORD = 2, G_SET = 3 };

static const uint32_t g_deep[4]  = { 0x0B6E4Fu, 0x1C63B0u, 0xBD5908u, 0x505050u };
static const uint32_t g_light[4] = { 0xC5DBCEu, 0xCED7E6u, 0xEFD7C5u, 0xD6D2CEu };
static const uint32_t g_card[4]  = { 0xE6EFE6u, 0xE6EBEFu, 0xF7EBDEu, 0xEFEBE6u };

/* ── 字号阶梯（与上一轮同 6 档；骑行 hero 64→56 给两条色带让位）───── */
enum {
    G_PX_HERO  = 56,
    G_PX_TITLE = 30,
    G_PX_VALUE = 22,
    G_PX_BODY  = 15,
    G_PX_SMALL = 12,
    G_PX_MICRO = 11,
};

/* ── 屏幕 ──────────────────────────────────────────────────────── */

enum {
    G_SCR_MAIN = 0,
    G_SCR_ROTATE,
    G_SCR_LONGPRESS,
    G_SCR_RIDE,
    G_SCR_NAV,
    G_SCR_RECORD,
    G_SCR_SETTINGS,
    G_SCR_DISPLAY,
    G_SCR_SENSOR,
    G_SCR_ABOUT,
    G_SCR_ANIM_ROTATE,
    G_SCR_ANIM_ENTER,
    G_SCR_ANIM_BACK,
    G_SCR_COUNT,
};

static const char *const g_screen_names[G_SCR_COUNT] = {
    "main", "rotate", "longpress", "ride", "nav",
    "record", "settings", "display", "sensor", "about",
    "anim_dial_rotate", "anim_enter_ride", "anim_back",
};

/* ── 小工具 ────────────────────────────────────────────────────── */

static lv_obj_t *s_scr;
static int s_font_use[128];

static lv_font_t *g_font(int px)
{
    if (px >= 0 && px < 128) {
        s_font_use[px]++;
    }
    return sim_font_cjk(px);
}

static lv_obj_t *g_lab(lv_obj_t *p, const char *txt, int px, uint32_t hex,
                       int x, int y)
{
    if (px >= 0 && px < 128) {
        s_font_use[px]++;
    }
    return d_label(p, txt, px, hex, x, y);
}

static lv_obj_t *g_lab_w(lv_obj_t *p, const char *txt, int px, uint32_t hex,
                         int x, int y, int w, lv_text_align_t align)
{
    if (px >= 0 && px < 128) {
        s_font_use[px]++;
    }
    return d_label_w(p, txt, px, hex, x, y, w, align);
}

static void g_legend(lv_obj_t *p, int y, const char *markup)
{
    s_font_use[G_PX_MICRO]++;
    d2_legend(p, y, G_PX_MICRO, G_MUTE, markup);
}

static void g_hair(lv_obj_t *p, int x, int y, int w)
{
    (void)d_hline(p, x, y, w, G_HAIR, LV_OPA_COVER);
}

static void g_top(lv_obj_t *p, const char *left, const char *right)
{
    g_lab(p, left, G_PX_SMALL, G_MUTE, 24, 13);
    g_lab_w(p, right, G_PX_SMALL, G_MUTE, 130, 13, 86, LV_TEXT_ALIGN_RIGHT);
}

/** 分区标题下的短色条：20×4，面积 80px²。 */
static void g_title_bar(lv_obj_t *p, int x, int y, uint32_t hex)
{
    (void)d_box(p, x, y, 20, 4, hex, LV_OPA_COVER, 2);
}

#define G_PTS_MAX 320
static lv_point_precise_t s_pts[G_PTS_MAX][2];
static int s_pts_n;

static void g_pts_reset(void)
{
    s_pts_n = 0;
}

static const lv_point_precise_t *g_seg(int x1, int y1, int x2, int y2)
{
    if (s_pts_n >= G_PTS_MAX) {
        s_pts_n = 0;
    }
    lv_point_precise_t *p = s_pts[s_pts_n++];

    p[0].x = x1;
    p[0].y = y1;
    p[1].x = x2;
    p[1].y = y2;
    return p;
}

/** 圆弧：opa 控制 indicator 透明度（转场半亮用）。 */
static lv_obj_t *g_arc(lv_obj_t *p, int cx, int cy, int d, int thickness,
                       int start, int span, uint32_t hex, bool rounded,
                       lv_opa_t opa)
{
    lv_obj_t *arc = lv_arc_create(p);

    lv_obj_set_size(arc, d, d);
    lv_obj_set_pos(arc, cx - d / 2, cy - d / 2);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(arc, 0, 0);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(arc, 0, 0);
    lv_obj_set_style_outline_width(arc, 0, 0);
    lv_obj_set_style_shadow_width(arc, 0, 0);

    lv_obj_set_style_arc_opa(arc, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_set_style_arc_width(arc, 0, LV_PART_MAIN);
    lv_obj_set_style_arc_rounded(arc, false, LV_PART_MAIN);

    lv_obj_set_style_arc_opa(arc, opa, LV_PART_INDICATOR);
    lv_obj_set_style_arc_width(arc, thickness, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, lv_color_hex(hex), LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(arc, rounded, LV_PART_INDICATOR);

    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_KNOB);
    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
    lv_obj_set_style_pad_all(arc, 0, LV_PART_KNOB);

    lv_arc_set_bg_angles(arc, ((start % 360) + 360) % 360,
                         (((start + span) % 360) + 360) % 360);
    lv_arc_set_rotation(arc, 0);
    lv_arc_set_range(arc, 0, 100);
    lv_arc_set_value(arc, 100);
    return arc;
}

static void g_tick(lv_obj_t *p, int cx, int cy, int deg, int r1, int r2,
                   int thickness, uint32_t hex)
{
    const double a = (double)deg * 3.14159265358979 / 180.0;
    const int x1 = cx + (int)lround(sin(a) * r1);
    const int y1 = cy - (int)lround(cos(a) * r1);
    const int x2 = cx + (int)lround(sin(a) * r2);
    const int y2 = cy - (int)lround(cos(a) * r2);

    (void)d2_poly(p, g_seg(x1, y1, x2, y2), 2, thickness, hex, true);
}

static void g_tiller(lv_obj_t *p, int cx, int cy, int deg, int r0, int r1)
{
    const double a = (double)deg * 3.14159265358979 / 180.0;
    const double sx = sin(a);
    const double sy = -cos(a);
    const double px = cos(a);
    const double py = sin(a);
    const int x0 = cx + (int)lround(sx * r0);
    const int y0 = cy + (int)lround(sy * r0);
    const int x1 = cx + (int)lround(sx * r1);
    const int y1 = cy + (int)lround(sy * r1);

    (void)d2_poly(p, g_seg(x0, y0, x1, y1), 2, 3, G_INK, true);
    (void)d2_poly(p, g_seg(x1 - (int)lround(px * 8),
                           y1 - (int)lround(py * 8),
                           x1 + (int)lround(px * 8),
                           y1 + (int)lround(py * 8)),
                  2, 3, G_INK, true);
}

/* ── 图标（纯几何；每种 ≤4 个对象）─────────────────────────────── */

enum {
    G_ICON_DIAL = 0,
    G_ICON_NAV,
    G_ICON_RECORD,
    G_ICON_SET,
    G_ICON_DISPLAY,
    G_ICON_SENSOR,
    G_ICON_SOUND,
    G_ICON_INFO,
    G_ICON_CADENCE,
};

static void g_icon(lv_obj_t *p, int kind, int cx, int cy, uint32_t hex)
{
    switch (kind) {
        case G_ICON_DIAL: {   /* 半圆表盘 + 指针 */
            (void)g_arc(p, cx, cy + 1, 20, 2, 135, 270, hex, false,
                        LV_OPA_COVER);
            (void)d2_poly(p, g_seg(cx, cy + 1, cx - 6, cy - 4), 2, 2, hex, true);
            (void)d_box(p, cx - 1, cy, 3, 3, hex, LV_OPA_COVER, 1);
            break;
        }
        case G_ICON_NAV: {    /* 右转箭头 */
            (void)d2_poly(p, g_seg(cx - 4, cy + 7, cx - 4, cy - 2), 2, 2,
                          hex, true);
            (void)d2_poly(p, g_seg(cx - 4, cy - 2, cx + 4, cy - 2), 2, 2,
                          hex, true);
            (void)d2_poly(p, g_seg(cx + 1, cy - 7, cx + 5, cy - 2), 2, 2,
                          hex, true);
            (void)d2_poly(p, g_seg(cx + 1, cy + 3, cx + 5, cy - 2), 2, 2,
                          hex, true);
            break;
        }
        case G_ICON_RECORD:   /* 三根柱 */
            (void)d_box(p, cx - 7, cy - 1, 3, 9, hex, LV_OPA_COVER, 1);
            (void)d_box(p, cx - 1, cy - 7, 3, 15, hex, LV_OPA_COVER, 1);
            (void)d_box(p, cx + 5, cy - 4, 3, 12, hex, LV_OPA_COVER, 1);
            break;
        case G_ICON_SET: {    /* 三条滑杆 + 旋钮 */
            for (int i = 0; i < 3; i++) {
                (void)d_box(p, cx - 8, cy - 5 + i * 5, 16, 2, hex,
                            LV_OPA_COVER, 1);
            }
            (void)d_box(p, cx + 1, cy - 7, 4, 4, hex, LV_OPA_COVER, 2);
            (void)d_box(p, cx - 5, cy - 2, 4, 4, hex, LV_OPA_COVER, 2);
            (void)d_box(p, cx + 4, cy + 3, 4, 4, hex, LV_OPA_COVER, 2);
            break;
        }
        case G_ICON_DISPLAY: { /* 显示器 */
            lv_obj_t *o = d_box(p, cx - 9, cy - 8, 18, 12, 0x000000u,
                                LV_OPA_TRANSP, 2);

            lv_obj_set_style_border_width(o, 2, 0);
            lv_obj_set_style_border_color(o, lv_color_hex(hex), 0);
            lv_obj_set_style_border_opa(o, LV_OPA_COVER, 0);
            (void)d_box(p, cx - 4, cy + 5, 8, 2, hex, LV_OPA_COVER, 1);
            break;
        }
        case G_ICON_SENSOR:   /* 心电波形 */
            (void)d2_poly(p, (const lv_point_precise_t[]){
                { cx - 9, cy }, { cx - 5, cy }, { cx - 3, cy - 6 },
                { cx, cy + 6 }, { cx + 2, cy - 2 }, { cx + 9, cy - 2 },
            }, 6, 2, hex, true);
            break;
        case G_ICON_SOUND: {  /* 喇叭 + 两声波 */
            (void)d2_poly(p, (const lv_point_precise_t[]){
                { cx - 7, cy - 2 }, { cx - 4, cy - 2 }, { cx + 1, cy - 6 },
                { cx + 1, cy + 6 }, { cx - 4, cy + 2 }, { cx - 7, cy + 2 },
                { cx - 7, cy - 2 },
            }, 7, 2, hex, true);
            (void)d2_poly(p, g_seg(cx + 4, cy - 3, cx + 6, cy), 2, 2, hex, true);
            break;
        }
        case G_ICON_INFO: {   /* i */
            (void)d2_ring(p, cx, cy, 17, 2, hex);
            (void)d_box(p, cx - 1, cy - 5, 3, 3, hex, LV_OPA_COVER, 1);
            (void)d_box(p, cx - 1, cy - 1, 3, 7, hex, LV_OPA_COVER, 1);
            break;
        }
        case G_ICON_CADENCE: {/* 曲柄圆 + 箭头 */
            (void)g_arc(p, cx, cy, 18, 2, 210, 300, hex, false, LV_OPA_COVER);
            (void)d2_poly(p, g_seg(cx + 8, cy - 4, cx + 9, cy + 1), 2, 2,
                          hex, true);
            (void)d2_poly(p, g_seg(cx + 9, cy + 1, cx + 4, cy + 2), 2, 2,
                          hex, true);
            break;
        }
        default:
            break;
    }
}

/** 浅底图标块：浅色圆角方块 + 1px 深色边，符号另画（面积 28²=784）。 */
static lv_obj_t *g_chip(lv_obj_t *p, int x, int y, int size, uint32_t light,
                        uint32_t deep)
{
    lv_obj_t *b = d_box(p, x, y, size, size, light, LV_OPA_COVER, 7);

    lv_obj_set_style_border_width(b, 1, 0);
    lv_obj_set_style_border_color(b, lv_color_hex(deep), 0);
    lv_obj_set_style_border_opa(b, LV_OPA_COVER, 0);
    return b;
}

/** 深底图标块：深色圆角方块 + 纸色符号（18²=324，阳光档最稳的色块）。 */
static lv_obj_t *g_chip_deep(lv_obj_t *p, int x, int y, int size, uint32_t deep)
{
    return d_box(p, x, y, size, size, deep, LV_OPA_COVER, size / 3);
}

static lv_obj_t *g_chip_flex(lv_obj_t *parent, int size, uint32_t light,
                             uint32_t deep)
{
    lv_obj_t *b = lv_obj_create(parent);

    lv_obj_remove_style_all(b);
    lv_obj_set_size(b, size, size);
    lv_obj_set_style_bg_color(b, lv_color_hex(light), 0);
    lv_obj_set_style_bg_opa(b, LV_OPA_COVER, 0);
    lv_obj_set_style_radius(b, 7, 0);
    lv_obj_set_style_border_width(b, 1, 0);
    lv_obj_set_style_border_color(b, lv_color_hex(deep), 0);
    lv_obj_set_style_border_opa(b, LV_OPA_COVER, 0);
    lv_obj_remove_flag(b, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(b, LV_OBJ_FLAG_CLICKABLE);
    return b;
}

/* ── 状态带 / 小图标 ───────────────────────────────────────────── */

/** 信号格：4 根柱，底对齐 y+13。 */
static void g_signal(lv_obj_t *p, int x, int y, uint32_t hex)
{
    static const int h[4] = { 4, 7, 10, 13 };

    for (int i = 0; i < 4; i++) {
        (void)d_box(p, x + i * 4, y + 13 - h[i], 3, h[i], hex,
                    LV_OPA_COVER, 1);
    }
}

/** 电池：18×9 外壳 + 正极 + 填充。fill 0..1。 */
static void g_battery(lv_obj_t *p, int x, int y, uint32_t deep, int fill_pct)
{
    lv_obj_t *o = d_box(p, x, y, 18, 9, 0x000000u, LV_OPA_TRANSP, 2);

    lv_obj_set_style_border_width(o, 1, 0);
    lv_obj_set_style_border_color(o, lv_color_hex(G_INK), 0);
    lv_obj_set_style_border_opa(o, LV_OPA_COVER, 0);
    (void)d_box(p, x + 18, y + 2, 2, 5, G_INK, LV_OPA_COVER, 1);

    {
        const int w = (14 * fill_pct) / 100;

        if (w > 0) {
            (void)d_box(p, x + 2, y + 2, w, 5, deep, LV_OPA_COVER, 1);
        }
    }
}

/** 时钟：14px 环 + 两根指针。 */
static void g_clock(lv_obj_t *p, int cx, int cy, uint32_t hex)
{
    (void)d2_ring(p, cx, cy, 14, 2, hex);
    (void)d2_poly(p, g_seg(cx, cy, cx, cy - 4), 2, 1, hex, true);
    (void)d2_poly(p, g_seg(cx, cy, cx + 3, cy + 1), 2, 1, hex, true);
}

/**
 * 底部状态带：GPS / 电量 / 时间，三组图标 + 数字，两根 3×16 色条分隔。
 * 带宽 24px（y=262..286），色块面积：图标 18²=324、色条 48。
 */
static void g_status_band(lv_obj_t *p)
{
    (void)d_box(p, 0, 262, 240, 24, G_CARD, LV_OPA_COVER, 0);
    g_hair(p, 0, 262, 240);

    /* GPS：蓝色信号格 + 颗数。 */
    g_signal(p, 30, 266, g_deep[G_NAV]);
    g_lab(p, "12", G_PX_MICRO, G_INK, 48, 265);

    /* 分隔色条 1：导航蓝。 */
    (void)d_box(p, 76, 266, 3, 16, g_deep[G_NAV], LV_OPA_COVER, 1);

    /* 电量：绿色电池 + 百分比。 */
    g_battery(p, 88, 269, g_deep[G_RIDE], 86);
    g_lab(p, "86%", G_PX_MICRO, G_INK, 110, 265);

    /* 分隔色条 2：记录橙。 */
    (void)d_box(p, 146, 266, 3, 16, g_deep[G_RECORD], LV_OPA_COVER, 1);

    /* 时间：近黑时钟 + 时间。 */
    g_clock(p, 162, 274, G_INK);
    g_lab(p, "14:32", G_PX_MICRO, G_INK, 174, 265);
}

/* ── 盘面 ──────────────────────────────────────────────────────── */

typedef struct {
    const char *name;
    const char *desc;
    const char *value;
    const char *unit;
    const char *sub;
} g_mode_t;

static const g_mode_t g_modes[4] = {
    { "骑行", "实时数据 · 上次骑行", "42.6", "km", "本周 68.4 km · 电量 86%" },
    { "导航", "路线 · 转向提示",     "8.4",  "km", "全程 10.0 km · 电量 86%" },
    { "记录", "历史 · 数据回顾",     "68.4", "km", "本周 3 次 · 电量 86%" },
    { "设置", "设备 · 显示 · 关于",  "86",   "%",  "固件 v1.2.6 · 电量 86%" },
};

static const int g_mode_icons[4] = {
    G_ICON_DIAL, G_ICON_NAV, G_ICON_RECORD, G_ICON_SET,
};

/**
 * @brief 盘面：双色轨道 + 选中扇区（浅 20% + 深边）+ 24 刻度 + 舵柄。
 *
 * @param half_a 旧扇区中心角（-1 = 不画），opa_a 旧扇区透明度
 * @param half_b 新扇区中心角（-1 = 不画），opa_b 新扇区透明度
 */
static void g_dial(lv_obj_t *p, int cx, int cy, int half_a, lv_opa_t opa_a,
                   int half_b, lv_opa_t opa_b, int mode, int ptr_deg,
                   bool progress)
{
    /* 整圈未选轨道：2px、26% 黑。 */
    (void)d2_ring(p, cx, cy, 160, 2, G_TRACK);

    /* 选中模式的 90° 象限用模式色，轨道从"单色圈"变成"双色圈"。 */
    (void)g_arc(p, cx, cy, 160, 2, mode * 90 - 135, 90, g_deep[mode], false,
                LV_OPA_COVER);

    if (half_a >= 0) {
        const int a = half_a - 90;

        (void)g_arc(p, cx, cy, 144, 24, a - 26, 52, g_light[mode], false, opa_a);
        (void)g_arc(p, cx, cy, 170, 2, a - 26, 52, g_deep[mode], false, opa_a);
    }
    if (half_b >= 0) {
        const int m2 = (mode + 1) % 4;
        const int a = half_b - 90;

        (void)g_arc(p, cx, cy, 144, 24, a - 26, 52, g_light[m2], false, opa_b);
        (void)g_arc(p, cx, cy, 170, 2, a - 26, 52, g_deep[m2], false, opa_b);
    }

    for (int i = 0; i < 24; i++) {
        const int deg = i * 15;
        const bool major = (i % 6 == 0);

        g_tick(p, cx, cy, deg, major ? 66 : 69, 74,
               major ? 3 : 1, major ? G_INK : G_TICK);
    }

    g_tiller(p, cx, cy, ptr_deg, 56, 84);

    if (progress) {
        lv_obj_t *pr;

        (void)g_arc(p, cx, cy, 128, 3, 135, 270, G_TRACK, true, LV_OPA_COVER);
        pr = g_arc(p, cx, cy, 128, 4, 135, 270, g_deep[G_RIDE], true,
                   LV_OPA_COVER);
        lv_arc_set_value(pr, 50);
    }
}

/** 模式名：12/3/6/9 点；选中 15px 近黑，未选 12px 灰。 */
static void g_mode_labels(lv_obj_t *p, int cx, int cy, int on)
{
    static const char *const names[4] = { "骑行", "导航", "记录", "设置" };
    static const int lx[4] = { 0, 1, 0, -1 };
    static const int ly[4] = { -1, 0, 1, 0 };

    for (int i = 0; i < 4; i++) {
        const bool sel = (i == on);
        const int px = sel ? G_PX_BODY : G_PX_SMALL;
        const int x = cx + lx[i] * 96 - 20;
        const int y = cy + ly[i] * 104 - (sel ? 10 : 8);

        g_lab_w(p, names[i], px, sel ? G_INK : G_MUTE, x, y, 40,
                LV_TEXT_ALIGN_CENTER);
    }
}

/** 盘心：图标底 + 模式名 / 描述 / 主值 / 副行。 */
static void g_hub(lv_obj_t *p, int cx, const g_mode_t *m, int mode)
{
    lv_obj_t *row = d_stack(p, cx - 80, 88, 160, 40, LV_FLEX_ALIGN_CENTER, 6);
    lv_obj_t *chip = g_chip_flex(row, 28, g_light[mode], g_deep[mode]);
    lv_obj_t *name = lv_label_create(row);

    g_icon(chip, g_mode_icons[mode], 14, 14, g_deep[mode]);

    lv_label_set_text(name, m->name);
    lv_obj_set_style_text_font(name, g_font(G_PX_TITLE), 0);
    lv_obj_set_style_text_color(name, lv_color_hex(G_INK), 0);

    g_lab_w(p, m->desc, G_PX_SMALL, G_MUTE, cx - 80, 126, 160,
            LV_TEXT_ALIGN_CENTER);

    {
        lv_obj_t *vrow = d_stack(p, cx - 60, 143, 120, 30,
                                 LV_FLEX_ALIGN_CENTER, 3);
        lv_obj_t *v = lv_label_create(vrow);

        lv_label_set_text(v, m->value);
        lv_obj_set_style_text_font(v, g_font(G_PX_VALUE), 0);
        lv_obj_set_style_text_color(v, lv_color_hex(G_INK), 0);

        {
            lv_obj_t *u = lv_label_create(vrow);

            lv_label_set_text(u, m->unit);
            lv_obj_set_style_text_font(u, g_font(G_PX_MICRO), 0);
            lv_obj_set_style_text_color(u, lv_color_hex(G_MUTE), 0);
            lv_obj_set_style_pad_bottom(u, 4, 0);
        }
    }

    g_hair(p, cx - 16, 175, 32);
    g_lab_w(p, m->sub, G_PX_MICRO, G_MUTE, cx - 80, 180, 160,
            LV_TEXT_ALIGN_CENTER);
}

/* ── 1/2/3. 主界面 / 旋转 / 长按 ──────────────────────────────── */

static void g_main_common(int screen)
{
    const bool rotate = (screen == G_SCR_ROTATE);
    const bool press = (screen == G_SCR_LONGPRESS);
    const int on = rotate ? 1 : 0;
    const int ptr = rotate ? 45 : 0;
    const g_mode_t *m = &g_modes[on];

    d_bg(s_scr, G_BG);
    g_top(s_scr, "模式", rotate ? "01 → 02" : "01 / 04");

    if (rotate) {
        /* 两位之间：旧扇区 50% 浅绿、新扇区 50% 浅蓝，指针 45°。 */
        g_dial(s_scr, 120, 146, 0, LV_OPA_50, 90, LV_OPA_50, G_NAV, ptr,
               false);
    } else {
        g_dial(s_scr, 120, 146, on * 90, LV_OPA_COVER, -1, LV_OPA_TRANSP, on,
               ptr, press);
    }

    g_mode_labels(s_scr, 120, 146, on);

    if (press) {
        lv_obj_t *row = d_stack(s_scr, 40, 88, 160, 40, LV_FLEX_ALIGN_CENTER, 6);
        lv_obj_t *chip = g_chip_flex(row, 28, g_light[G_RIDE], g_deep[G_RIDE]);
        lv_obj_t *name = lv_label_create(row);

        g_icon(chip, G_ICON_DIAL, 14, 14, g_deep[G_RIDE]);
        lv_label_set_text(name, m->name);
        lv_obj_set_style_text_font(name, g_font(G_PX_TITLE), 0);
        lv_obj_set_style_text_color(name, lv_color_hex(G_INK), 0);

        g_lab_w(s_scr, m->desc, G_PX_SMALL, G_MUTE, 40, 126, 160,
                LV_TEXT_ALIGN_CENTER);
        g_lab_w(s_scr, "长按 1 确认", G_PX_SMALL, G_MUTE, 40, 150, 160,
                LV_TEXT_ALIGN_CENTER);
        g_lab_w(s_scr, "50%", G_PX_VALUE, G_INK, 40, 170, 160,
                LV_TEXT_ALIGN_CENTER);
    } else {
        g_hub(s_scr, 120, m, on);
    }

    g_status_band(s_scr);

    g_legend(s_scr, 292,
             "#" G_INK_S " 1# 下一个 · 长按进入    #" G_INK_S " 2# 返回 · 长按开始");
}

static void g_main(lv_obj_t *scr)
{
    (void)scr;
    g_main_common(G_SCR_MAIN);
}

static void g_rotate(lv_obj_t *scr)
{
    (void)scr;
    g_main_common(G_SCR_ROTATE);
}

static void g_longpress(lv_obj_t *scr)
{
    (void)scr;
    g_main_common(G_SCR_LONGPRESS);
}

