/** 速度区间带：0-30 / 30-45 / 45-60 三段冷→暖，游标 3×20。 */
static void g_speed_band(lv_obj_t *p, int y, double speed)
{
    const int x0 = 52;
    const int w = 164;
    const int w1 = 82;
    const int w2 = 41;

    g_lab(p, "速度", G_PX_MICRO, G_MUTE, 24, y + 2);

    (void)d_box(p, x0, y, w1, 18, g_light[G_NAV], LV_OPA_COVER, 0);
    (void)d_box(p, x0 + w1, y, w2, 18, g_light[G_RIDE], LV_OPA_COVER, 0);
    (void)d_box(p, x0 + w1 + w2, y, w2, 18, g_light[G_RECORD], LV_OPA_COVER, 0);

    /* 段边界 1px 近黑，保证三段在阳光档下还有分界。 */
    (void)d_box(p, x0 + w1, y, 1, 18, G_INK, LV_OPA_COVER, 0);
    (void)d_box(p, x0 + w1 + w2, y, 1, 18, G_INK, LV_OPA_COVER, 0);

    g_lab(p, "0", G_PX_MICRO, G_INK, x0 + 4, y + 3);
    g_lab(p, "30", G_PX_MICRO, G_INK, x0 + w1 - 12, y + 3);
    g_lab(p, "60", G_PX_MICRO, G_INK, x0 + w - 16, y + 3);

    {
        int x = x0 + (int)lround(w * speed / 60.0);

        if (x < x0 + 1) {
            x = x0 + 1;
        }
        if (x > x0 + w - 4) {
            x = x0 + w - 4;
        }
        (void)d_box(p, x, y - 2, 3, 22, G_INK, LV_OPA_COVER, 1);
    }
}

/** 心率分区条：5 段（灰/蓝/绿/橙/红），当前段深色 + Z 标号。 */
static void g_hr_band(lv_obj_t *p, int y, int bpm, int zone)
{
    static const uint32_t zc[5] = { 0xD6D2CEu, 0xCED7E6u, 0xC5DBCEu,
                                    0xEFD7C5u, 0xE8CCC4u };
    static const uint32_t zd[5] = { 0x8F8A7Fu, 0x1C63B0u, 0x0B6E4Fu,
                                    0xBD5908u, 0xA62B1Fu };
    const int x0 = 96;
    const int w = 120;
    const int sw = 24;

    g_lab(p, "心率", G_PX_MICRO, G_MUTE, 24, y - 10);
    g_lab(p, "142", G_PX_VALUE, G_INK, 24, y - 2);
    g_lab(p, "bpm", G_PX_MICRO, G_MUTE, 66, y + 5);

    for (int i = 0; i < 5; i++) {
        const bool on = (i == zone - 1);

        (void)d_box(p, x0 + i * sw, y, sw, 20, on ? zd[i] : zc[i],
                    LV_OPA_COVER, 0);
    }
    (void)d_box(p, x0 + (zone - 1) * sw, y, 1, 20, G_INK, LV_OPA_COVER, 0);
    (void)d_box(p, x0 + zone * sw, y, 1, 20, G_INK, LV_OPA_COVER, 0);
    {
        char buf[8];

        snprintf(buf, sizeof(buf), "Z%d", zone);
        g_lab_w(p, buf, G_PX_MICRO, G_INK, x0 + (zone - 1) * sw, y + 3, sw,
                LV_TEXT_ALIGN_CENTER);
    }
    (void)bpm;
}

static void g_metric(lv_obj_t *p, int cx, int y, const char *label,
                     const char *value)
{
    g_lab_w(p, label, G_PX_MICRO, G_MUTE, cx - 30, y, 60,
            LV_TEXT_ALIGN_CENTER);
    g_lab_w(p, value, G_PX_VALUE, G_INK, cx - 30, y + 13, 60,
            LV_TEXT_ALIGN_CENTER);
}

static void g_ride(lv_obj_t *scr)
{
    d_bg(scr, G_BG);
    g_top(scr, "骑行中", "GPS 12");

    /* 页点：3 页，当前页用骑行绿（9px=64px²，过 40px² 阈值）。 */
    for (int i = 0; i < 3; i++) {
        (void)d_box(scr, 99 + i * 16, 17, 9, 9,
                    i == 0 ? g_deep[G_RIDE] : G_TRACK, LV_OPA_COVER, 4);
    }

    /* 270° 仪表：中心 (120,106)、d=152、7px。 */
    {
        lv_obj_t *arc = lv_arc_create(scr);

        lv_obj_set_size(arc, 152, 152);
        lv_obj_set_pos(arc, 44, 30);
        lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_style_pad_all(arc, 0, 0);
        lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
        lv_obj_set_style_border_width(arc, 0, 0);
        lv_obj_set_style_outline_width(arc, 0, 0);
        lv_obj_set_style_shadow_width(arc, 0, 0);
        lv_obj_set_style_arc_width(arc, 7, LV_PART_MAIN);
        lv_obj_set_style_arc_color(arc, lv_color_hex(G_TRACK), LV_PART_MAIN);
        lv_obj_set_style_arc_rounded(arc, true, LV_PART_MAIN);
        lv_obj_set_style_arc_width(arc, 7, LV_PART_INDICATOR);
        lv_obj_set_style_arc_color(arc, lv_color_hex(g_deep[G_RIDE]),
                                   LV_PART_INDICATOR);
        lv_obj_set_style_arc_rounded(arc, true, LV_PART_INDICATOR);
        lv_obj_set_style_bg_color(arc, lv_color_hex(G_INK), LV_PART_KNOB);
        lv_obj_set_style_bg_opa(arc, LV_OPA_COVER, LV_PART_KNOB);
        lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
        lv_obj_set_style_pad_all(arc, 3, LV_PART_KNOB);
        lv_arc_set_bg_angles(arc, 0, 270);
        lv_arc_set_rotation(arc, 135);
        lv_arc_set_range(arc, 0, 60);
        lv_arc_set_value(arc, 25);
    }

    for (int i = 0; i < 7; i++) {
        g_tick(scr, 120, 106, (225 + i * 45) % 360, 78, 84, 1, G_TICK);
    }

    {
        lv_obj_t *stack = d_stack(scr, 40, 64, 160, 56, LV_FLEX_ALIGN_CENTER, 0);
        lv_obj_t *v = lv_label_create(stack);

        lv_label_set_text(v, "24.8");
        lv_obj_set_style_text_font(v, g_font(G_PX_HERO), 0);
        lv_obj_set_style_text_color(v, lv_color_hex(G_INK), 0);
    }
    g_lab_w(scr, "km/h", G_PX_SMALL, G_MUTE, 40, 122, 160,
            LV_TEXT_ALIGN_CENTER);

    g_speed_band(scr, 184, 24.8);
    g_hr_band(scr, 216, 142, 4);

    g_metric(scr, 48, 250, "里程 km", "12.4");
    g_metric(scr, 96, 250, "时间", "0:42");
    g_metric(scr, 144, 250, "踏频 rpm", "86");
    g_metric(scr, 192, 250, "海拔 m", "326");

    g_legend(scr, 296,
             "#" G_INK_S " 1# 切页    #" G_INK_S " 2# 返回 · 长按结束");
}

