/** 真 vmap 视口：y=44..196（240×152）。 */
static void g_nav_map(lv_obj_t *scr)
{
#ifdef SIM_WITH_UI
    lv_obj_t *holder = lv_obj_create(scr);

    lv_obj_remove_style_all(holder);
    lv_obj_set_size(holder, 240, 152);
    lv_obj_set_pos(holder, 0, 44);
    lv_obj_set_style_bg_color(holder, lv_color_hex(G_CARD), 0);
    lv_obj_set_style_bg_opa(holder, LV_OPA_COVER, 0);
    lv_obj_remove_flag(holder, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(holder, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    s_vmap = vmap_view_create(holder, 240, 152, VMAP_CANVAS_MARGIN);
    if (s_vmap == NULL) {
        g_lab(scr, "vmap create failed", G_PX_MICRO, G_MUTE, 16, 120);
        return;
    }

    double lon = 0.0;
    double lat = 0.0;

    vmap_boot_lonlat(&lon, &lat);
    vmap_view_bind_arrow_layer(s_vmap, holder);
    vmap_view_set_font(s_vmap, sim_font_cjk(15));
    vmap_view_set_center_icon(s_vmap, navi_arrow_get(NAVI_ARROW_DARK));
    vmap_view_set_view(s_vmap, lon, lat, 14);
    vmap_view_center_on(s_vmap, lon, lat);
