/* ── 场景入口（13 屏）─────────────────────────────────────────── */

static void g_build(lv_obj_t *scr, int screen)
{
    switch (screen) {
        case G_SCR_ROTATE:      g_rotate(scr); break;
        case G_SCR_LONGPRESS:   g_longpress(scr); break;
        case G_SCR_RIDE:        g_ride(scr); break;
        case G_SCR_NAV:         g_nav(scr); break;
        case G_SCR_RECORD:      g_record(scr); break;
        case G_SCR_SETTINGS:    g_settings(scr); break;
        case G_SCR_DISPLAY:     g_display(scr); break;
        case G_SCR_SENSOR:      g_sensor(scr); break;
        case G_SCR_ABOUT:       g_about(scr); break;
        case G_SCR_ANIM_ROTATE: g_anim_rotate(scr); break;
        case G_SCR_ANIM_ENTER:  g_anim_enter(scr); break;
        case G_SCR_ANIM_BACK:   g_anim_back(scr); break;
        default:                g_main(scr); break;
    }
}

static int g_count_objs(lv_obj_t *o)
{
    int n = 1;
    const uint32_t c = lv_obj_get_child_count(o);

    for (uint32_t i = 0; i < c; i++) {
        n += g_count_objs(lv_obj_get_child(o, (int32_t)i));
    }
    return n;
}

static void g_rebuild(int screen)
{
    if (screen < 0 || screen >= G_SCR_COUNT) {
        screen = G_SCR_MAIN;
    }
#ifdef SIM_WITH_UI
    g_vmap_stop();
#endif
    lv_obj_clean(s_scr);
    g_pts_reset();
    memset(s_font_use, 0, sizeof(s_font_use));
    g_build(s_scr, screen);
    printf("design4: screen=%s objects=%d fonts", g_screen_names[screen],
           g_count_objs(s_scr));
    for (int i = 0; i < 128; i++) {
        if (s_font_use[i] != 0) {
            printf(" %d=%d", i, s_font_use[i]);
        }
    }
    printf("\n");
    fflush(stdout);
}

static int g_screen_from_env(void)
{
    const char *s = getenv("SIM_DESIGN_SCREEN");

    if (s == NULL || s[0] == '\0') {
        return G_SCR_MAIN;
    }
    for (int i = 0; i < G_SCR_COUNT; i++) {
        if (strcmp(s, g_screen_names[i]) == 0) {
            return i;
        }
    }
    if (strcmp(s, "menu") == 0) {
        return G_SCR_SETTINGS;
    }
    if (s[0] >= '0' && s[0] <= '9' && s[1] == '\0') {
        return s[0] - '0';
    }
    fprintf(stderr,
            "sim: unknown SIM_DESIGN_SCREEN=%s "
            "(main|rotate|longpress|ride|nav|record|settings|display|sensor|"
            "about|anim_dial_rotate|anim_enter_ride|anim_back)\n", s);
    return G_SCR_MAIN;
}

static void g_key_timer(lv_timer_t *t)
{
    (void)t;
    for (;;) {
        int k = sim_display_take_raw_key();

        if (k == 0) {
            break;
        }
        if (k >= '1' && k <= '9') {
            g_rebuild(k - '1');
        } else if (k == '0') {
            g_rebuild(G_SCR_ABOUT);
        }
    }
}

void scene_design_g_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    (void)cfg;
    s_scr = scr;
    g_rebuild(g_screen_from_env());
    lv_timer_create(g_key_timer, 60, NULL);
}
